import * as React from "react";
import { cn } from "@/lib/utils";

export interface InputProps
  extends React.InputHTMLAttributes<HTMLInputElement> {
  /**
   * Optional label rendered above the input as a real `<label>` element.
   * When provided, an `id` is auto-generated (via `useId`) and associated
   * with the input via `htmlFor`. Any `id` or `aria-label` passed explicitly
   * in `props` takes precedence.
   *
   * Matches the convention used across the apps:
   * `block text-sm font-medium` in the secondary text color above the field.
   */
  label?: React.ReactNode;
  /**
   * Supporting text below the field -- a format, a range, a minimum. Reaches
   * the field through `aria-describedby`, so it is read with the label rather
   * than as a separate stop.
   */
  hint?: React.ReactNode;
  /**
   * What is wrong with the current value. Replaces `hint` while set, marks the
   * field `aria-invalid`, and announces through `role="alert"` -- a field whose
   * submit button greys out with nothing on screen leaves the user guessing
   * which of the form's values it objected to.
   */
  error?: React.ReactNode;
  /**
   * Accessible name for the reveal button on a `type="password"` field, in the
   * masked state ("Show password").
   *
   * The button renders only when BOTH this and `hideLabel` are given: the DS
   * ships no translations, and an icon-only control with no name is worse than
   * no control at all.
   */
  revealLabel?: string;
  /** Accessible name for the same button while the value is visible ("Hide password"). */
  hideLabel?: string;
}

/** Open eye / struck-through eye, at the size the field's trailing slot allows. */
function EyeIcon({ off }: { off: boolean }) {
  return (
    <svg
      className="w-4 h-4"
      viewBox="0 0 20 20"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.6"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden
    >
      <path d="M1.5 10S4.7 4.5 10 4.5 18.5 10 18.5 10 15.3 15.5 10 15.5 1.5 10 1.5 10Z" />
      <circle cx="10" cy="10" r="2.5" />
      {off && <path d="M3 17 17 3" />}
    </svg>
  );
}

const Input = React.forwardRef<HTMLInputElement, InputProps>(
  (
    {
      className,
      type,
      label,
      hint,
      error,
      revealLabel,
      hideLabel,
      id: idProp,
      "aria-describedby": describedByProp,
      ...props
    },
    ref
  ) => {
    const autoId = React.useId();
    const id = idProp ?? (label !== undefined ? autoId : undefined);
    const messageId = `${autoId}-message`;

    const [revealed, setRevealed] = React.useState(false);
    const canReveal =
      type === "password" && revealLabel !== undefined && hideLabel !== undefined;
    // Swapping the type is what reveals the value; the field keeps its own
    // state so a parent re-render does not re-mask a value mid-read.
    const resolvedType = canReveal && revealed ? "text" : type;

    const message = error ?? hint;
    const describedBy =
      [describedByProp, message !== undefined ? messageId : undefined]
        .filter(Boolean)
        .join(" ") || undefined;

    const inputEl = (
      <input
        type={resolvedType}
        id={id}
        aria-invalid={error !== undefined ? true : props["aria-invalid"]}
        aria-describedby={describedBy}
        className={cn(
          // Field shape: regular radius (a button is the full-round one), a
          // solid border, no fill of its own, and the deboss recess -- so a
          // field reads as cut INTO whatever it sits on while a button sits on
          // top of it. Transparent rather than `surface`, so it takes the tone
          // of its container instead of punching a white well into a tinted one.
          "flex h-control-md w-full rounded-lg",
          "border border-[var(--color-border-light)]",
          "bg-transparent shadow-deboss",
          "px-3 py-2 text-sm",
          "file:border-0 file:bg-transparent file:text-sm file:font-medium",
          "placeholder:text-[var(--color-text-muted-light)]",
          "wj-focus-ring",
          "disabled:cursor-not-allowed disabled:opacity-50",
          "hover:border-[var(--color-warm-300)]",
          "disabled:hover:border-[var(--color-border-light)]",
          "transition-colors",
          "dark:border-[var(--color-border-dark)]",
          "dark:hover:border-[var(--color-neutral-700)]",
          "dark:disabled:hover:border-[var(--color-border-dark)]",
          "dark:placeholder:text-[var(--color-text-muted-dark)]",
          // Clear the trailing reveal button, and take the error border over
          // the resting one in both themes.
          canReveal && "pe-11",
          error !== undefined &&
            "border-[var(--color-error-500)] dark:border-[var(--color-error-500)] hover:border-[var(--color-error-500)] dark:hover:border-[var(--color-error-500)]",
          className
        )}
        ref={ref}
        {...props}
      />
    );

    // The field alone, with nothing to wrap it for: the common case stays a
    // bare <input> so a caller's layout is unchanged.
    if (label === undefined && message === undefined && !canReveal) {
      return inputEl;
    }

    const field = canReveal ? (
      <div className="relative">
        {inputEl}
        <button
          type="button"
          // Takes no tab stop of its own ahead of the field it belongs to: it
          // sits after the input in the DOM, so Tab reaches it in reading order.
          onClick={() => setRevealed((v) => !v)}
          // The name flips between the two labels, which already states the
          // state; an aria-pressed on top would read as "Hide password, pressed".
          aria-label={revealed ? hideLabel : revealLabel}
          title={revealed ? hideLabel : revealLabel}
          className={cn(
            "wj-focus-ring absolute end-1 top-1/2 -translate-y-1/2",
            "flex h-8 w-8 items-center justify-center rounded-full",
            "text-[var(--color-text-muted-light)] dark:text-[var(--color-text-muted-dark)]",
            "hover:text-[var(--color-text-primary-light)] dark:hover:text-[var(--color-text-primary-dark)]"
          )}
        >
          <EyeIcon off={revealed} />
        </button>
      </div>
    ) : (
      inputEl
    );

    return (
      <div className="flex flex-col gap-1">
        {label !== undefined && (
          <label
            htmlFor={id}
            className="block text-sm font-medium text-[var(--color-text-secondary-light)] dark:text-[var(--color-text-secondary-dark)]"
          >
            {label}
          </label>
        )}
        {field}
        {message !== undefined && (
          <p
            id={messageId}
            // Only the error is a live region -- a hint is static supporting
            // text, and announcing it on render would talk over the label.
            role={error !== undefined ? "alert" : undefined}
            className={cn(
              "text-xs",
              error !== undefined
                ? "text-[var(--color-error-700)] dark:text-[var(--color-error-500)]"
                : "text-[var(--color-text-muted-light)] dark:text-[var(--color-text-muted-dark)]"
            )}
          >
            {message}
          </p>
        )}
      </div>
    );
  }
);
Input.displayName = "Input";

export { Input };
